L["Abandon these quests? Their progress and associated quest items will be lost."] = "Abandonner ces quêtes ? Leur progression et les objets de quête associés seront perdus."
L["Accept and turn in quests"] = "Accepter et rendre les quêtes"
L["Accept party invites from friends"] = "Accepter les invitations de groupe des amis"
